insert into public.articles (id,title,title_ar,title_en,slug,content,content_ar,content_en,summary,summary_ar,summary_en,author,tags,featured,published,views,metadata) values ('7eca1ac1-fe96-51ca-9814-ef773cc715be','التوحيد في حياة المسلم','التوحيد في حياة المسلم','Zikr Article','zikr-article-expansion-01','التوحيد ليس فكرة نظرية، بل هو أن يقصد المسلم الله وحده بالعبادة والخوف والرجاء والمحبة والاستعانة. يظهر أثره في الصلاة والصدق والإنفاق وترك الظلم؛ فكل عمل صالح يصبح أوضح مقصدًا حين يتحرر القلب من التعلق بالمخلوقين. يبدأ بناء التوحيد بتدبر أسماء الله وآياته، ثم بمراجعة النية في الأعمال اليومية، وبالابتعاد عن كل ما يناقض إخلاص العبادة أو يفتح باب الغلو والخرافة.','التوحيد ليس فكرة نظرية، بل هو أن يقصد المسلم الله وحده بالعبادة والخوف والرجاء والمحبة والاستعانة. يظهر أثره في الصلاة والصدق والإنفاق وترك الظلم؛ فكل عمل صالح يصبح أوضح مقصدًا حين يتحرر القلب من التعلق بالمخلوقين. يبدأ بناء التوحيد بتدبر أسماء الله وآياته، ثم بمراجعة النية في الأعمال اليومية، وبالابتعاد عن كل ما يناقض إخلاص العبادة أو يفتح باب الغلو والخرافة.','Original Arabic editorial article prepared for Zikr.','التوحيد ليس فكرة نظرية، بل هو أن يقصد المسلم الله وحده بالعبادة والخوف والرجاء والمحبة والاستعانة. يظهر أثره في الصلاة والصدق والإنفاق وترك الظلم؛ فكل عمل صالح يصبح أوضح مقصدًا حين…','التوحيد ليس فكرة نظرية، بل هو أن يقصد المسلم الله وحده بالعبادة والخوف والرجاء والمحبة والاستعانة. يظهر أثره في الصلاة والصدق والإنفاق وترك الظلم؛ فكل عمل صالح يصبح أوضح مقصدًا حين…','Original article summary.','فريق تحرير ذِكر',ARRAY['إيمان','تزكية','أسرة','معرفة'],true,true,0,'{"editorial":true,"source_note":"Original editorial content; Quran and hadith references should be checked in primary sources."}') on conflict (slug) do update set title=excluded.title,title_ar=excluded.title_ar,title_en=excluded.title_en,content=excluded.content,content_ar=excluded.content_ar,content_en=excluded.content_en,summary=excluded.summary,summary_ar=excluded.summary_ar,summary_en=excluded.summary_en,author=excluded.author,tags=e