insert into public.articles (id,title,title_ar,title_en,slug,content,content_ar,content_en,summary,summary_ar,summary_en,author,tags,featured,published,views,metadata) values ('a8f6135c-a132-5f28-8b36-bbbca377c4be','كيف نتدبر القرآن؟','كيف نتدبر القرآن؟','Zikr Article','zikr-article-expansion-02','التدبر أعمق من سرعة القراءة، وهو جمع القلب مع الآية وفهم سياقها ثم سؤال النفس عن أثرها العملي. يمكن للقارئ أن يقرأ مقطعًا قصيرًا، يراجع معاني الكلمات، يربط الآية بما قبلها وما بعدها، ثم يختار عملًا واحدًا يطبقه. لا يصح أن نستخرج حكمًا تفصيليًا من آية دون علم، بل نرجع إلى التفاسير المعتبرة وأهل الاختصاص عند الإشكال.','التدبر أعمق من سرعة القراءة، وهو جمع القلب مع الآية وفهم سياقها ثم سؤال النفس عن أثرها العملي. يمكن للقارئ أن يقرأ مقطعًا قصيرًا، يراجع معاني الكلمات، يربط الآية بما قبلها وما بعدها، ثم يختار عملًا واحدًا يطبقه. لا يصح أن نستخرج حكمًا تفصيليًا من آية دون علم، بل نرجع إلى التفاسير المعتبرة وأهل الاختصاص عند الإشكال.','Original Arabic editorial article prepared for Zikr.','التدبر أعمق من سرعة القراءة، وهو جمع القلب مع الآية وفهم سياقها ثم سؤال النفس عن أثرها العملي. يمكن للقارئ أن يقرأ مقطعًا قصيرًا، يراجع معاني الكلمات، يربط الآية بما قبلها وما بعده…','التدبر أعمق من سرعة القراءة، وهو جمع القلب مع الآية وفهم سياقها ثم سؤال النفس عن أثرها العملي. يمكن للقارئ أن يقرأ مقطعًا قصيرًا، يراجع معاني الكلمات، يربط الآية بما قبلها وما بعده…','Original article summary.','فريق تحرير ذِكر',ARRAY['إيمان','تزكية','أسرة','معرفة'],true,true,0,'{"editorial":true,"source_note":"Original editorial content; Quran and hadith references should be checked in primary sources."}') on conflict (slug) do update set title=excluded.title,title_ar=excluded.title_ar,title_en=excluded.title_en,content=excluded.content,content_ar=excluded.content_ar,content_en=excluded.content_en,summary=excluded.summary,summary_ar=excluded.summary_ar,summary_en=excluded.summary_en,author=excluded.author,tags=excluded.tags,featured=excluded.featured,published=true,metadata=excluded.metadata;
insert into public.articles (id,title,title_ar,title_en,slug,content,content_ar,content_en,summary,summary_ar,summary_en,author,tags,featured,published,views,metadata) values ('416bfe79-8c33-542f-a49d-67adb83743b7','الصلاة وبناء اليوم','الصلاة وبناء اليوم','Zikr Article','zikr-article-expansion-03','الصلاة تقسم اليوم إلى محطات يقظة وطمأنينة، وتربط العمل الدنيوي بالغاية الأخروية. المحافظة عليها تحتاج إلى أسباب عملية: معرفة الوقت، الاستعداد قبل الأذان، تقليل المشتتات، وصحبة تعين على الثبات. إذا فاتت صلاة بسبب نوم أو نسيان فليبادر المسلم إلى أدائها، وليتعلم من السبب دون أن يتحول الندم إلى يأس.','الصلاة تقسم اليوم إلى محطات يقظة وطمأنينة، وتربط العمل الدنيوي بالغاية الأخروية. المحافظة عليها تحتاج إلى أسباب عملية: معرفة الوقت، الاستعداد قبل الأذان، تقليل المشتتات، وصحبة تعين على الثبات. إذا فاتت صلاة بسبب نوم أو نسيان فليبادر المسلم إلى أدائها، وليتعلم من السبب دون أن يتحول الندم إلى يأس.','Original Arabic editorial article prepared for Zikr.','الصلاة تقسم اليوم إلى محطات يقظة وطمأنينة، وتربط العمل الدنيوي بالغاية الأخروية. المحافظة عليها تحتاج إلى أسباب عملية: معرفة الوقت، الاستعداد قبل الأذان، تقليل المشتتات، وصحبة تعين…','الصلاة تقسم اليوم إلى محطات يقظة وطمأنينة، وتربط العمل الدنيوي بالغاية الأخروية. المحافظة عليها تحتاج إلى أسباب عملية: معرفة الوقت، الاستعداد قبل الأذان، تقليل المشتتات، وصحبة تعين…','Original article summary.','فريق تحرير ذِكر',ARRAY['إيمان','تزكية','أسرة','معرفة'],true,true,0,'{"editorial":true,"source_note":"Original editorial content; Quran and hadith references should be checked in primary sources."}') on conflict (slug) do update set title=excluded.title,title_ar=excluded.title_ar,title_en=excluded.title_en,content=excluded.content,content_ar=excluded.content_ar,content_en=excluded.content_en,summary=excluded.summary,summary_ar=excluded.summary_ar,summary_en=excluded.summary_en,author=excluded.author,tags=excluded.tags,featured=excluded.featured,published=true,metadata=excluded.metadata;
insert into public.articles (id,title,title_ar,title_en,slug,content,content_ar,content_en,summary,summary_ar,summary_en,author,tags,featured,published,views,metadata) values ('4b20fb3b-7692-547b-ad3a-e9f619eba99f','فقه الاختلاف وآداب الحوار','فقه الاختلاف وآداب الحوار','Zikr Article','zikr-article-expansion-04','الاختلاف في مسائل الاجتهاد لا يبرر السب أو إسقاط الأخوة. من الأدب أن يفرق المسلم بين القطعي والظني، وأن ينقل قول المخالف بأمانة، وأن يسأل عن الدليل قبل الحكم. وعند المسائل التي تمس الفتوى أو حياة الناس ينبغي الرجوع إلى عالم موثوق يعرف الواقع والنصوص، لا إلى مقطع مجهول أو منشور مقتطع.','الاختلاف في مسائل الاجتهاد لا يبرر السب أو إسقاط الأخوة. من الأدب أن يفرق المسلم بين القطعي والظني، وأن ينقل قول المخالف بأمانة، وأن يسأل عن الدليل قبل الحكم. وعند المسائل التي تمس الفتوى أو حياة الناس ينبغي الرجوع إلى عالم موثوق يعرف الواقع والنصوص، لا إلى مقطع مجهول أو منشور مقتطع.','Original Arabic editorial article prepared for Zikr.','الاختلاف في مسائل الاجتهاد لا يبرر السب أو إسقاط الأخوة. من الأدب أن يفرق المسلم بين القطعي والظني، وأن ينقل قول المخالف بأمانة، وأن يسأل عن الدليل قبل الحكم. وعند المسائل التي تمس…','الاختلاف في مسائل الاجتهاد لا يبرر السب أو إسقاط الأخوة. من الأدب أن يفرق المسلم بين القطعي والظني، وأن ينقل قول المخالف بأمانة، وأن يسأل عن الدليل قبل الحكم. وعند المسائل التي تمس…','Original article summary.','فريق تحرير ذِكر',ARRAY['إيمان','تزكية','أسرة','معرفة'],true,true,0,'{"editorial":true,"source_note":"Original editorial content; Quran and hadith references should be checked in primary sources."}') on conflict (slug) do update set title=excluded.title,title_ar=excluded.title_ar,title_en=excluded.title_en,content=excluded.content,content_ar=excluded.content_ar,content_en=excluded.content_en,summary=excluded.summary,summary_ar=excluded.summary_ar,summary_en=excluded.summary_en,author=excluded.author,tags=excluded.tags,featured=excluded.featured,published=true,metadata=excluded.metadata;
insert into public.articles (id,title,title_ar,title_en,slug,content,content_ar,content_en,summary,summary_ar,summary_en,author,tags,featured,published,views,metadata) values ('27dca70a-f3c1-56ee-af0f-6de5bb473ec6','التوبة وإعادة البداية','التوبة وإعادة البداية','Zikr Article','zikr-article-expansion-05','التوبة الصادقة تجمع الإقلاع عن الذنب والندم والعزم على عدم العودة ورد الحقوق إلى أصحابها. لا ينبغي أن ينتظر الإنسان شعورًا مثاليًا حتى يبدأ؛ بل يبدأ بخطوة واضحة، ويغلق أبواب المعصية، ويستبدل العادة السيئة بعمل صالح، ويطلب العون من الله. وإذا عاد إلى الذنب عاد إلى التوبة ولم يستسلم لوسوسة أن الطريق انتهى.','التوبة الصادقة تجمع الإقلاع عن الذنب والندم والعزم على عدم العودة ورد الحقوق إلى أصحابها. لا ينبغي أن ينتظر الإنسان شعورًا مثاليًا حتى يبدأ؛ بل يبدأ بخطوة واضحة، ويغلق أبواب المعصية، ويستبدل العادة السيئة بعمل صالح، ويطلب العون من الله. وإذا عاد إلى الذنب عاد إلى التوبة ولم يستسلم لوسوسة أن الطريق انتهى.','Original Arabic editorial article prepared for Zikr.','التوبة الصادقة تجمع الإقلاع عن الذنب والندم والعزم على عدم العودة ورد الحقوق إلى أصحابها. لا ينبغي أن ينتظر الإنسان شعورًا مثاليًا حتى يبدأ؛ بل يبدأ بخطوة واضحة، ويغلق أبواب المعصي…','التوبة الصادقة تجمع الإقلاع عن الذنب والندم والعزم على عدم العودة ورد الحقوق إلى أصحابها. لا ينبغي أن ينتظر الإنسان شعورًا مثاليًا حتى يبدأ؛ بل يبدأ بخطوة واضحة، ويغلق أبواب المعصي…','Original article summary.','فريق تحرير ذِكر',ARRAY['إيمان','تزكية','أسرة','معرفة'],true,true,0,'{"editorial":true,"source_note":"Original editorial content; Quran and hadith references should be checked in primary sources."}') on conflict (slug) do update set title=excluded.title,title_ar=excluded.title_ar,title_en=excluded.title_en,content=excluded.content,content_ar=excluded.content_ar,content_en=excluded.content_en,summary=excluded.summary,summary_ar=excluded.summary_ar,summary_en=excluded.summary_en,author=excluded.author,tags=excluded.tags,featured=excluded.featured,published=true,metadata=excluded.metadata;
insert into public.articles (id,title,title_ar,title_en,slug,content,content_ar,content_en,summary,summary_ar,summary_en,author,tags,featured,published,views,metadata) values ('c996e09c-da8b-5edd-972b-0c577d8d4bf0','الأمانة الرقمية','الأمانة الرقمية','Zikr Article','zikr-article-expansion-06','الهاتف والإنترنت أمانة مثل المال والوقت. يدخل في الأمانة ألا ننشر خبرًا بلا تحقق، وألا نقتطع كلامًا يغير معناه، وألا نستخدم صور الناس أو أعمالهم دون حق. ومن حسن العبادة أن نضع حدودًا للوقت، ونحمي الخصوصية، ونستخدم التقنية في التعلم وصلة الرحم وخدمة الخير بدل المقارنة والجدال المستمر.','الهاتف والإنترنت أمانة مثل المال والوقت. يدخل في الأمانة ألا ننشر خبرًا بلا تحقق، وألا نقتطع كلامًا يغير معناه، وألا نستخدم صور الناس أو أعمالهم دون حق. ومن حسن العبادة أن نضع حدودًا للوقت، ونحمي الخصوصية، ونستخدم التقنية في التعلم وصلة الرحم وخدمة الخير بدل المقارنة والجدال المستمر.','Original Arabic editorial article prepared for Zikr.','الهاتف والإنترنت أمانة مثل المال والوقت. يدخل في الأمانة ألا ننشر خبرًا بلا تحقق، وألا نقتطع كلامًا يغير معناه، وألا نستخدم صور الناس أو أعمالهم دون حق. ومن حسن العبادة أن نضع حدود…','الهاتف والإنترنت أمانة مثل المال والوقت. يدخل في الأمانة ألا ننشر خبرًا بلا تحقق، وألا نقتطع كلامًا يغير معناه، وألا نستخدم صور الناس أو أعمالهم دون حق. ومن حسن العبادة أن نضع حدود…','Original article summary.','فريق تحرير ذِكر',ARRAY['إيمان','تزكية','أسرة','معرفة'],false,true,0,'{"editorial":true,"source_note":"Original editorial content; Quran and hadith references should be checked in primary sources."}') on conflict (slug) do update set title=excluded.title,title_ar=excluded.title_ar,title_en=excluded.title_en,content=excluded.content,content_ar=excluded.content_ar,content_en=excluded.content_en,summary=excluded.summary,summary_ar=excluded.summary_ar,summary_en=excluded.summary_en,author=excluded.author,tags=excluded.tags,featured=excluded.featured,published=true,metadata=excluded.metadata;
insert into public.articles (id,title,title_ar,title_en,slug,content,content_ar,content_en,summary,summary_ar,summary_en,author,tags,featured,published,views,metadata) values ('adf3e468-aa86-516e-93dc-5430ea0be6a0','الأسرة المسلمة والحوار','الأسرة المسلمة والحوار','Zikr Article','zikr-article-expansion-07','الأسرة لا تُبنى بالأوامر وحدها، بل بالقدوة والاستماع والرحمة والحدود الواضحة. يحتاج الأبناء إلى وقت نوعي، وإلى شرح سبب القواعد، وإلى مساحة للسؤال دون تخويف. ويمكن للأسرة أن تجعل للقرآن والصلاة والصدقة ومراجعة الأسبوع عادات صغيرة ثابتة، مع مراعاة اختلاف الأعمار والقدرات.','الأسرة لا تُبنى بالأوامر وحدها، بل بالقدوة والاستماع والرحمة والحدود الواضحة. يحتاج الأبناء إلى وقت نوعي، وإلى شرح سبب القواعد، وإلى مساحة للسؤال دون تخويف. ويمكن للأسرة أن تجعل للقرآن والصلاة والصدقة ومراجعة الأسبوع عادات صغيرة ثابتة، مع مراعاة اختلاف الأعمار والقدرات.','Original Arabic editorial article prepared for Zikr.','الأسرة لا تُبنى بالأوامر وحدها، بل بالقدوة والاستماع والرحمة والحدود الواضحة. يحتاج الأبناء إلى وقت نوعي، وإلى شرح سبب القواعد، وإلى مساحة للسؤال دون تخويف. ويمكن للأسرة أن تجعل لل…','الأسرة لا تُبنى بالأوامر وحدها، بل بالقدوة والاستماع والرحمة والحدود الواضحة. يحتاج الأبناء إلى وقت نوعي، وإلى شرح سبب القواعد، وإلى مساحة للسؤال دون تخويف. ويمكن للأسرة أن تجعل لل…','Original article summary.','فريق تحرير ذِكر',ARRAY['إيمان','تزكية','أسرة','معرفة'],false,true,0,'{"editorial":true,"source_note":"Original editorial content; Quran and hadith references should be checked in primary sources."}') on conflict (slug) do update set title=excluded.title,title_ar=excluded.title_ar,title_en=excluded.title_en,content=excluded.content,content_ar=excluded.content_ar,content_en=excluded.content_en,summary=excluded.summary,summary_ar=excluded.summary_ar,summary_en=excluded.summary_en,author=excluded.author,tags=excluded.tags,featured=excluded.featured,published=true,metadata=excluded.metadata;
insert into public.articles (id,title,title_ar,title_en,slug,content,content_ar,content_en,summary,summary_ar,summary_en,author,tags,featured,published,views,metadata) values ('d4a5c8e5-bd63-5062-93b9-75079a199562','العمل والنية الصالحة','العمل والنية الصالحة','Zikr Article','zikr-article-expansion-08','العمل المباح يمكن أن يتحول إلى عبادة بالنية الصالحة وإتقان الواجب وحفظ حقوق الناس. لا تعني النية أن نقبل الغش أو التقصير، بل تجعل المسلم أكثر التزامًا بالمواعيد وأصدق في الوعد وأبعد عن استغلال الضعيف. ومن فقه الرزق أن يسعى الإنسان، ويوازن بين الكسب والراحة والأسرة، ويستعين بالله دون ترك الأسباب.','العمل المباح يمكن أن يتحول إلى عبادة بالنية الصالحة وإتقان الواجب وحفظ حقوق الناس. لا تعني النية أن نقبل الغش أو التقصير، بل تجعل المسلم أكثر التزامًا بالمواعيد وأصدق في الوعد وأبعد عن استغلال الضعيف. ومن فقه الرزق أن يسعى الإنسان، ويوازن بين الكسب والراحة والأسرة، ويستعين بالله دون ترك الأسباب.','Original Arabic editorial article prepared for Zikr.','العمل المباح يمكن أن يتحول إلى عبادة بالنية الصالحة وإتقان الواجب وحفظ حقوق الناس. لا تعني النية أن نقبل الغش أو التقصير، بل تجعل المسلم أكثر التزامًا بالمواعيد وأصدق في الوعد وأبع…','العمل المباح يمكن أن يتحول إلى عبادة بالنية الصالحة وإتقان الواجب وحفظ حقوق الناس. لا تعني النية أن نقبل الغش أو التقصير، بل تجعل المسلم أكثر التزامًا بالمواعيد وأصدق في الوعد وأبع…','Original article summary.','فريق تحرير ذِكر',ARRAY['إيمان','تزكية','أسرة','معرفة'],false,true,0,'{"editorial":true,"source_note":"Original editorial content; Quran and hadith references should be checked in primary sources."}') on conflict (slug) do update set title=excluded.title,title_ar=excluded.title_ar,title_en=excluded.title_en,content=excluded.content,content_ar=excluded.content_ar,content_en=excluded.content_en,summary=excluded.summary,summary_ar=excluded.summary_ar,summary_en=excluded.summary_en,author=excluded.author,tags=excluded.tags,featured=excluded.featured,published=true,metadata=excluded.metadata;
insert into public.articles (id,title,title_ar,title_en,slug,content,content_ar,content_en,summary,summary_ar,summary_en,author,tags,featured,published,views,metadata) values ('05332466-10de-58f5-b902-97f106e15da9','الصدقة وأثرها الاجتماعي','الصدقة وأثرها الاجتماعي','Zikr Article','zikr-article-expansion-09','الصدقة ليست مالًا فقط؛ منها تفريج كربة، وتعليم نافع، وكلمة طيبة، وإماطة أذى. الأفضل أن تكون نافعة مستمرة بقدر الاستطاعة، وأن تحفظ كرامة المحتاج ولا تتحول إلى تصوير واستعراض. قبل التبرع لمشروع عام، يتحقق المسلم من الجهة، ووضوح المصرف، وطرق الحماية من الاحتيال.','الصدقة ليست مالًا فقط؛ منها تفريج كربة، وتعليم نافع، وكلمة طيبة، وإماطة أذى. الأفضل أن تكون نافعة مستمرة بقدر الاستطاعة، وأن تحفظ كرامة المحتاج ولا تتحول إلى تصوير واستعراض. قبل التبرع لمشروع عام، يتحقق المسلم من الجهة، ووضوح المصرف، وطرق الحماية من الاحتيال.','Original Arabic editorial article prepared for Zikr.','الصدقة ليست مالًا فقط؛ منها تفريج كربة، وتعليم نافع، وكلمة طيبة، وإماطة أذى. الأفضل أن تكون نافعة مستمرة بقدر الاستطاعة، وأن تحفظ كرامة المحتاج ولا تتحول إلى تصوير واستعراض. قبل ال…','الصدقة ليست مالًا فقط؛ منها تفريج كربة، وتعليم نافع، وكلمة طيبة، وإماطة أذى. الأفضل أن تكون نافعة مستمرة بقدر الاستطاعة، وأن تحفظ كرامة المحتاج ولا تتحول إلى تصوير واستعراض. قبل ال…','Original article summary.','فريق تحرير ذِكر',ARRAY['إيمان','تزكية','أسرة','معرفة'],false,true,0,'{"editorial":true,"source_note":"Original editorial content; Quran and hadith references should be checked in primary sources."}') on conflict (slug) do update set title=excluded.title,title_ar=excluded.title_ar,title_en=excluded.title_en,content=excluded.content,content_ar=excluded.content_ar,content_en=excluded.content_en,summary=excluded.summary,summary_ar=excluded.summary_ar,summary_en=excluded.summary_en,author=excluded.author,tags=excluded.tags,featured=excluded.featured,published=true,metadata=excluded.metadata;
insert into public.articles (id,title,title_ar,title_en,slug,content,content_ar,content_en,summary,summary_ar,summary_en,author,tags,featured,published,views,metadata) values ('eb76b987-7999-54c1-97be-e3fca001881d','الصبر بين المعنى والعمل','الصبر بين المعنى والعمل','Zikr Article','zikr-article-expansion-10','الصبر لا يعني السكون أمام الظلم أو ترك العلاج، بل الثبات على الطاعة، وضبط النفس عن الحرام، وتحمل البلاء مع استعمال الوسائل المشروعة. يحتاج الصبر إلى شبكة دعم ودعاء ونوم وغذاء وتنظيم، فالبدن أمانة. وإذا تحول الحزن إلى عجز طويل أو خطر على النفس، فطلب المساعدة المختصة لا يناقض التوكل.','الصبر لا يعني السكون أمام الظلم أو ترك العلاج، بل الثبات على الطاعة، وضبط النفس عن الحرام، وتحمل البلاء مع استعمال الوسائل المشروعة. يحتاج الصبر إلى شبكة دعم ودعاء ونوم وغذاء وتنظيم، فالبدن أمانة. وإذا تحول الحزن إلى عجز طويل أو خطر على النفس، فطلب المساعدة المختصة لا يناقض التوكل.','Original Arabic editorial article prepared for Zikr.','الصبر لا يعني السكون أمام الظلم أو ترك العلاج، بل الثبات على الطاعة، وضبط النفس عن الحرام، وتحمل البلاء مع استعمال الوسائل المشروعة. يحتاج الصبر إلى شبكة دعم ودعاء ونوم وغذاء وتنظي…','الصبر لا يعني السكون أمام الظلم أو ترك العلاج، بل الثبات على الطاعة، وضبط النفس عن الحرام، وتحمل البلاء مع استعمال الوسائل المشروعة. يحتاج الصبر إلى شبكة دعم ودعاء ونوم وغذاء وتنظي…','Original article summary.','فريق تحرير ذِكر',ARRAY['إيمان','تزكية','أسرة','معرفة'],false,true,0,'{"editorial":true,"source_note":"Original editorial content; Quran and hadith references should be checked in primary sources."}') on conflict (slug) do update set title=excluded.title,title_ar=excluded.title_ar,title_en=excluded.title_en,content=excluded.content,content_ar=excluded.content_ar,content_en=excluded.content_en,summary=excluded.summary,summary_ar=excluded.summary_ar,summary_en=excluded.summary_en,author=excluded.author,tags=excluded.tags,featured=excluded.featured,published=true,metadata=excluded.metadata;
insert into public.articles (id,title,title_ar,title_en,slug,content,content_ar,content_en,summary,summary_ar,summary_en,author,tags,featured,published,views,metadata) values ('e156baee-44e0-5a82-b00c-ed143fea01b3','الرحمة بالحيوان والبيئة','الرحمة بالحيوان والبيئة','Zikr Article','zikr-article-expansion-11','الرحمة خلق إسلامي يشمل الإنسان والحيوان والبيئة. يبدأ ذلك بعدم تعذيب الحيوان، وعدم إلقاء المخلفات، وترشيد الماء والطعام، وإصلاح الضرر عند وقوعه. وتربية الأطفال على هذه المعاني تجعل العبادة سلوكًا يوميًا لا شعارات موسمية.','الرحمة خلق إسلامي يشمل الإنسان والحيوان والبيئة. يبدأ ذلك بعدم تعذيب الحيوان، وعدم إلقاء المخلفات، وترشيد الماء والطعام، وإصلاح الضرر عند وقوعه. وتربية الأطفال على هذه المعاني تجعل العبادة سلوكًا يوميًا لا شعارات موسمية.','Original Arabic editorial article prepared for Zikr.','الرحمة خلق إسلامي يشمل الإنسان والحيوان والبيئة. يبدأ ذلك بعدم تعذيب الحيوان، وعدم إلقاء المخلفات، وترشيد الماء والطعام، وإصلاح الضرر عند وقوعه. وتربية الأطفال على هذه المعاني تجعل…','الرحمة خلق إسلامي يشمل الإنسان والحيوان والبيئة. يبدأ ذلك بعدم تعذيب الحيوان، وعدم إلقاء المخلفات، وترشيد الماء والطعام، وإصلاح الضرر عند وقوعه. وتربية الأطفال على هذه المعاني تجعل…','Original article summary.','فريق تحرير ذِكر',ARRAY['إيمان','تزكية','أسرة','معرفة'],false,true,0,'{"editorial":true,"source_note":"Original editorial content; Quran and hadith references should be checked in primary sources."}') on conflict (slug) do update set title=excluded.title,title_ar=excluded.title_ar,title_en=excluded.title_en,content=excluded.content,content_ar=excluded.content_ar,content_en=excluded.content_en,summary=excluded.summary,summary_ar=excluded.summary_ar,summary_en=excluded.summary_en,author=excluded.author,tags=excluded.tags,featured=excluded.featured,published=true,metadata=excluded.metadata;
insert into public.articles (id,title,title_ar,title_en,slug,content,content_ar,content_en,summary,summary_ar,summary_en,author,tags,featured,published,views,metadata) values ('be992093-4cdc-5d4b-84ca-5a070f13b197','الزكاة والعدل المالي','الزكاة والعدل المالي','Zikr Article','zikr-article-expansion-12','الزكاة عبادة مالية لها شروط وأنصبة ومصارف، فلا يصح حسابها بالتخمين في الحالات المعقدة. يتعلم المسلم الفرق بين الزكاة والصدقة والوقف، ويحفظ سجلًا لأمواله وديونه، ويسأل أهل العلم عند اختلاف الأصول التجارية أو العملات. المقصد تزكية المال وحماية الفقير وبناء التكافل دون إهدار حقوق المستحقين.','الزكاة عبادة مالية لها شروط وأنصبة ومصارف، فلا يصح حسابها بالتخمين في الحالات المعقدة. يتعلم المسلم الفرق بين الزكاة والصدقة والوقف، ويحفظ سجلًا لأمواله وديونه، ويسأل أهل العلم عند اختلاف الأصول التجارية أو العملات. المقصد تزكية المال وحماية الفقير وبناء التكافل دون إهدار حقوق المستحقين.','Original Arabic editorial article prepared for Zikr.','الزكاة عبادة مالية لها شروط وأنصبة ومصارف، فلا يصح حسابها بالتخمين في الحالات المعقدة. يتعلم المسلم الفرق بين الزكاة والصدقة والوقف، ويحفظ سجلًا لأمواله وديونه، ويسأل أهل العلم عند…','الزكاة عبادة مالية لها شروط وأنصبة ومصارف، فلا يصح حسابها بالتخمين في الحالات المعقدة. يتعلم المسلم الفرق بين الزكاة والصدقة والوقف، ويحفظ سجلًا لأمواله وديونه، ويسأل أهل العلم عند…','Original article summary.','فريق تحرير ذِكر',ARRAY['إيمان','تزكية','أسرة','معرفة'],false,true,0,'{"editorial":true,"source_note":"Original editorial content; Quran and hadith references should be checked in primary sources."}') on conflict (slug) do update set title=excluded.title,title_ar=excluded.title_ar,title_en=excluded.title_en,content=excluded.content,content_ar=excluded.content_ar,content_en=excluded.content_en,summary=excluded.summary,summary_ar=excluded.summary_ar,summary_en=excluded.summary_en,author=excluded.author,tags=excluded.tags,featured=excluded.featured,published=true,metadata=excluded.metadata;
insert into public.articles (id,title,title_ar,title_en,slug,content,content_ar,content_en,summary,summary_ar,summary_en,author,tags,featured,published,views,metadata) values ('ee35c7b6-7526-58ba-914b-11357e15b05e','السيرة كمنهج قيادة','السيرة كمنهج قيادة','Zikr Article','zikr-article-expansion-13','السيرة النبوية ليست سردًا للمعارك فقط، بل مدرسة في بناء الإنسان والمؤسسة والمجتمع. نرى فيها التخطيط والهجرة والعهود والشورى، ونرى كذلك الرحمة بالمخالف والوفاء بالوعد. قراءة السيرة الجيدة تذكر درجة الرواية وتفصل بين النص الثابت والقصة الشعبية، ثم تستخرج درسًا قابلًا للتطبيق.','السيرة النبوية ليست سردًا للمعارك فقط، بل مدرسة في بناء الإنسان والمؤسسة والمجتمع. نرى فيها التخطيط والهجرة والعهود والشورى، ونرى كذلك الرحمة بالمخالف والوفاء بالوعد. قراءة السيرة الجيدة تذكر درجة الرواية وتفصل بين النص الثابت والقصة الشعبية، ثم تستخرج درسًا قابلًا للتطبيق.','Original Arabic editorial article prepared for Zikr.','السيرة النبوية ليست سردًا للمعارك فقط، بل مدرسة في بناء الإنسان والمؤسسة والمجتمع. نرى فيها التخطيط والهجرة والعهود والشورى، ونرى كذلك الرحمة بالمخالف والوفاء بالوعد. قراءة السيرة …','السيرة النبوية ليست سردًا للمعارك فقط، بل مدرسة في بناء الإنسان والمؤسسة والمجتمع. نرى فيها التخطيط والهجرة والعهود والشورى، ونرى كذلك الرحمة بالمخالف والوفاء بالوعد. قراءة السيرة …','Original article summary.','فريق تحرير ذِكر',ARRAY['إيمان','تزكية','أسرة','معرفة'],false,true,0,'{"editorial":true,"source_note":"Original editorial content; Quran and hadith references should be checked in primary sources."}') on conflict (slug) do update set title=excluded.title,title_ar=excluded.title_ar,title_en=excluded.title_en,content=excluded.content,content_ar=excluded.content_ar,content_en=excluded.content_en,summary=excluded.summary,summary_ar=excluded.summary_ar,summary_en=excluded.summary_en,author=excluded.author,tags=excluded.tags,featured=excluded.featured,published=true,metadata=excluded.metadata;
insert into public.articles (id,title,title_ar,title_en,slug,content,content_ar,content_en,summary,summary_ar,summary_en,author,tags,featured,published,views,metadata) values ('3dab8758-5742-5b56-bdf6-6316d03f4fab','طلب العلم والتحقق','طلب العلم والتحقق','Zikr Article','zikr-article-expansion-14','طالب العلم يبدأ بتصحيح النية وتحديد سؤال واضح واختيار كتاب أو معلم مناسب. لا يكفي حفظ الاقتباسات؛ بل يفهم المصطلحات، ويميز الحديث الصحيح من الضعيف، ويعرف أن اختلاف العلماء له أصول. وفي عصر البحث السريع، ينبغي تسجيل المصدر وتاريخ الوصول وعدم تحويل الذكاء الاصطناعي أو نتائج البحث إلى بديل عن أهل الاختصاص.','طالب العلم يبدأ بتصحيح النية وتحديد سؤال واضح واختيار كتاب أو معلم مناسب. لا يكفي حفظ الاقتباسات؛ بل يفهم المصطلحات، ويميز الحديث الصحيح من الضعيف، ويعرف أن اختلاف العلماء له أصول. وفي عصر البحث السريع، ينبغي تسجيل المصدر وتاريخ الوصول وعدم تحويل الذكاء الاصطناعي أو نتائج البحث إلى بديل عن أهل الاختصاص.','Original Arabic editorial article prepared for Zikr.','طالب العلم يبدأ بتصحيح النية وتحديد سؤال واضح واختيار كتاب أو معلم مناسب. لا يكفي حفظ الاقتباسات؛ بل يفهم المصطلحات، ويميز الحديث الصحيح من الضعيف، ويعرف أن اختلاف العلماء له أصول.…','طالب العلم يبدأ بتصحيح النية وتحديد سؤال واضح واختيار كتاب أو معلم مناسب. لا يكفي حفظ الاقتباسات؛ بل يفهم المصطلحات، ويميز الحديث الصحيح من الضعيف، ويعرف أن اختلاف العلماء له أصول.…','Original article summary.','فريق تحرير ذِكر',ARRAY['إيمان','تزكية','أسرة','معرفة'],false,true,0,'{"editorial":true,"source_note":"Original editorial content; Quran and hadith references should be checked in primary sources."}') on conflict (slug) do update set title=excluded.title,title_ar=excluded.title_ar,title_en=excluded.title_en,content=excluded.content,content_ar=excluded.content_ar,content_en=excluded.content_en,summary=excluded.summary,summary_ar=excluded.summary_ar,summary_en=excluded.summary_en,author=excluded.author,tags=excluded.tags,featured=excluded.featured,published=true,metadata=excluded.metadata;
insert into public.articles (id,title,title_ar,title_en,slug,content,content_ar,content_en,summary,summary_ar,summary_en,author,tags,featured,published,views,metadata) values ('130329fb-9782-54a6-8eb4-aa770148dc85','الذكر والصحة النفسية','الذكر والصحة النفسية','Zikr Article','zikr-article-expansion-15','الذكر يطمئن القلب ويعيد ترتيب الانتباه، لكنه لا يلغي أسباب العلاج والدعم الاجتماعي. يمكن للمسلم أن يجعل له وردًا قصيرًا ثابتًا بعد الصلوات وقبل النوم، مع تنفس هادئ ومراجعة للنعم. وإذا ظهرت أعراض شديدة أو مستمرة، فالاستعانة بالطبيب أو المختص واجبة من باب حفظ النفس.','الذكر يطمئن القلب ويعيد ترتيب الانتباه، لكنه لا يلغي أسباب العلاج والدعم الاجتماعي. يمكن للمسلم أن يجعل له وردًا قصيرًا ثابتًا بعد الصلوات وقبل النوم، مع تنفس هادئ ومراجعة للنعم. وإذا ظهرت أعراض شديدة أو مستمرة، فالاستعانة بالطبيب أو المختص واجبة من باب حفظ النفس.','Original Arabic editorial article prepared for Zikr.','الذكر يطمئن القلب ويعيد ترتيب الانتباه، لكنه لا يلغي أسباب العلاج والدعم الاجتماعي. يمكن للمسلم أن يجعل له وردًا قصيرًا ثابتًا بعد الصلوات وقبل النوم، مع تنفس هادئ ومراجعة للنعم. و…','الذكر يطمئن القلب ويعيد ترتيب الانتباه، لكنه لا يلغي أسباب العلاج والدعم الاجتماعي. يمكن للمسلم أن يجعل له وردًا قصيرًا ثابتًا بعد الصلوات وقبل النوم، مع تنفس هادئ ومراجعة للنعم. و…','Original article summary.','فريق تحرير ذِكر',ARRAY['إيمان','تزكية','أسرة','معرفة'],false,true,0,'{"editorial":true,"source_note":"Original editorial content; Quran and hadith references should be checked in primary sources."}') on conflict (slug) do update set title=excluded.title,title_ar=excluded.title_ar,title_en=excluded.title_en,content=excluded.content,content_ar=excluded.content_ar,content_en=excluded.content_en,summary=excluded.summary,summary_ar=excluded.summary_ar,summary_en=excluded.summary_en,author=excluded.author,tags=excluded.tags,featured=excluded.featured,published=true,metadata=excluded.metadata;
insert into public.articles (id,title,title_ar,title_en,slug,content,content_ar,content_en,summary,summary_ar,summary_en,author,tags,featured,published,views,metadata) values ('caa18dc3-710a-596d-a40f-73def47aea93','الحج والعمرة: معاني الرحلة','الحج والعمرة: معاني الرحلة','Zikr Article','zikr-article-expansion-16','الحج يجمع التوحيد والذكر والمساواة والانضباط واحترام المكان والإنسان. الاستعداد يبدأ بتعلم المناسك من مصدر موثوق، وإدارة القدرة المالية والصحية، وترك الجدال والأذى. لا ينبغي تحويل العبادة إلى سباق تصوير؛ فالمقصود حضور القلب وتعظيم الشعائر وخدمة الرفقة.','الحج يجمع التوحيد والذكر والمساواة والانضباط واحترام المكان والإنسان. الاستعداد يبدأ بتعلم المناسك من مصدر موثوق، وإدارة القدرة المالية والصحية، وترك الجدال والأذى. لا ينبغي تحويل العبادة إلى سباق تصوير؛ فالمقصود حضور القلب وتعظيم الشعائر وخدمة الرفقة.','Original Arabic editorial article prepared for Zikr.','الحج يجمع التوحيد والذكر والمساواة والانضباط واحترام المكان والإنسان. الاستعداد يبدأ بتعلم المناسك من مصدر موثوق، وإدارة القدرة المالية والصحية، وترك الجدال والأذى. لا ينبغي تحويل …','الحج يجمع التوحيد والذكر والمساواة والانضباط واحترام المكان والإنسان. الاستعداد يبدأ بتعلم المناسك من مصدر موثوق، وإدارة القدرة المالية والصحية، وترك الجدال والأذى. لا ينبغي تحويل …','Original article summary.','فريق تحرير ذِكر',ARRAY['إيمان','تزكية','أسرة','معرفة'],false,true,0,'{"editorial":true,"source_note":"Original editorial content; Quran and hadith references should be checked in primary sources."}') on conflict (slug) do update set title=excluded.title,title_ar=excluded.title_ar,title_en=excluded.title_en,content=excluded.content,content_ar=excluded.content_ar,content_en=excluded.content_en,summary=excluded.summary,summary_ar=excluded.summary_ar,summary_en=excluded.summary_en,author=excluded.author,tags=excluded.tags,featured=excluded.featured,published=true,metadata=excluded.metadata;
insert into public.articles (id,title,title_ar,title_en,slug,content,content_ar,content_en,summary,summary_ar,summary_en,author,tags,featured,published,views,metadata) values ('7dcaae65-c7f2-55ab-9dc8-22d61b86d7a4','أخلاق التجارة','أخلاق التجارة','Zikr Article','zikr-article-expansion-17','التاجر المسلم يصدق في الوصف، يبين العيب، يفي بالموعد، ولا يستغل جهل المشتري أو حاجته. التسويق الرقمي لا يغير هذه الأخلاق، فالمبالغة المضللة والآراء الوهمية والخصومات الوهمية صور من أكل المال بالباطل. ومن البركة وضوح سياسة الاسترجاع وحفظ بيانات العملاء.','التاجر المسلم يصدق في الوصف، يبين العيب، يفي بالموعد، ولا يستغل جهل المشتري أو حاجته. التسويق الرقمي لا يغير هذه الأخلاق، فالمبالغة المضللة والآراء الوهمية والخصومات الوهمية صور من أكل المال بالباطل. ومن البركة وضوح سياسة الاسترجاع وحفظ بيانات العملاء.','Original Arabic editorial article prepared for Zikr.','التاجر المسلم يصدق في الوصف، يبين العيب، يفي بالموعد، ولا يستغل جهل المشتري أو حاجته. التسويق الرقمي لا يغير هذه الأخلاق، فالمبالغة المضللة والآراء الوهمية والخصومات الوهمية صور من…','التاجر المسلم يصدق في الوصف، يبين العيب، يفي بالموعد، ولا يستغل جهل المشتري أو حاجته. التسويق الرقمي لا يغير هذه الأخلاق، فالمبالغة المضللة والآراء الوهمية والخصومات الوهمية صور من…','Original article summary.','فريق تحرير ذِكر',ARRAY['إيمان','تزكية','أسرة','معرفة'],false,true,0,'{"editorial":true,"source_note":"Original editorial content; Quran and hadith references should be checked in primary sources."}') on conflict (slug) do update set title=excluded.title,title_ar=excluded.title_ar,title_en=excluded.title_en,content=excluded.content,content_ar=excluded.content_ar,content_en=excluded.content_en,summary=excluded.summary,summary_ar=excluded.summary_ar,summary_en=excluded.summary_en,author=excluded.author,tags=excluded.tags,featured=excluded.featured,published=true,metadata=excluded.metadata;
insert into public.articles (id,title,title_ar,title_en,slug,content,content_ar,content_en,summary,summary_ar,summary_en,author,tags,featured,published,views,metadata) values ('53ea2259-1853-54d0-9485-b57841989876','إدارة الوقت بالعبادة','إدارة الوقت بالعبادة','Zikr Article','zikr-article-expansion-18','الوقت رأس مال لا يعود. تساعد الصلاة والورد القرآني على بناء علامات ثابتة في اليوم، ثم تُقسم الأعمال إلى مهم وعاجل، مع فترات راحة. لا يحتاج المسلم إلى خطة مثالية؛ يحتاج إلى عادة صغيرة قابلة للتكرار ومراجعة أسبوعية تزيل ما لا ينفع.','الوقت رأس مال لا يعود. تساعد الصلاة والورد القرآني على بناء علامات ثابتة في اليوم، ثم تُقسم الأعمال إلى مهم وعاجل، مع فترات راحة. لا يحتاج المسلم إلى خطة مثالية؛ يحتاج إلى عادة صغيرة قابلة للتكرار ومراجعة أسبوعية تزيل ما لا ينفع.','Original Arabic editorial article prepared for Zikr.','الوقت رأس مال لا يعود. تساعد الصلاة والورد القرآني على بناء علامات ثابتة في اليوم، ثم تُقسم الأعمال إلى مهم وعاجل، مع فترات راحة. لا يحتاج المسلم إلى خطة مثالية؛ يحتاج إلى عادة صغي…','الوقت رأس مال لا يعود. تساعد الصلاة والورد القرآني على بناء علامات ثابتة في اليوم، ثم تُقسم الأعمال إلى مهم وعاجل، مع فترات راحة. لا يحتاج المسلم إلى خطة مثالية؛ يحتاج إلى عادة صغي…','Original article summary.','فريق تحرير ذِكر',ARRAY['إيمان','تزكية','أسرة','معرفة'],false,true,0,'{"editorial":true,"source_note":"Original editorial content; Quran and hadith references should be checked in primary sources."}') on conflict (slug) do update set title=excluded.title,title_ar=excluded.title_ar,title_en=excluded.title_en,content=excluded.content,content_ar=excluded.content_ar,content_en=excluded.content_en,summary=excluded.summary,summary_ar=excluded.summary_ar,summary_en=excluded.summary_en,author=excluded.author,tags=excluded.tags,featured=excluded.featured,published=true,metadata=excluded.metadata;
insert into public.articles (id,title,title_ar,title_en,slug,content,content_ar,content_en,summary,summary_ar,summary_en,author,tags,featured,published,views,metadata) values ('b181b8dd-d853-59c8-b15c-da34e9b37576','التواضع والعفو','التواضع والعفو','Zikr Article','zikr-article-expansion-19','التواضع ليس احتقار النفس، بل قبول الحق وعدم احتكار الفضل. والعفو لا يعني إلغاء الحدود أو تمكين المعتدي، بل اختيار الإصلاح حين يكون آمنًا وممكنًا. في الأسرة والعمل، يبدأ ذلك بالاعتذار الصريح، ونسبة الفضل لأهله، وترك الانتقام الذي يوسع الجرح.','التواضع ليس احتقار النفس، بل قبول الحق وعدم احتكار الفضل. والعفو لا يعني إلغاء الحدود أو تمكين المعتدي، بل اختيار الإصلاح حين يكون آمنًا وممكنًا. في الأسرة والعمل، يبدأ ذلك بالاعتذار الصريح، ونسبة الفضل لأهله، وترك الانتقام الذي يوسع الجرح.','Original Arabic editorial article prepared for Zikr.','التواضع ليس احتقار النفس، بل قبول الحق وعدم احتكار الفضل. والعفو لا يعني إلغاء الحدود أو تمكين المعتدي، بل اختيار الإصلاح حين يكون آمنًا وممكنًا. في الأسرة والعمل، يبدأ ذلك بالاعتذ…','التواضع ليس احتقار النفس، بل قبول الحق وعدم احتكار الفضل. والعفو لا يعني إلغاء الحدود أو تمكين المعتدي، بل اختيار الإصلاح حين يكون آمنًا وممكنًا. في الأسرة والعمل، يبدأ ذلك بالاعتذ…','Original article summary.','فريق تحرير ذِكر',ARRAY['إيمان','تزكية','أسرة','معرفة'],false,true,0,'{"editorial":true,"source_note":"Original editorial content; Quran and hadith references should be checked in primary sources."}') on conflict (slug) do update set title=excluded.title,title_ar=excluded.title_ar,title_en=excluded.title_en,content=excluded.content,content_ar=excluded.content_ar,content_en=excluded.content_en,summary=excluded.summary,summary_ar=excluded.summary_ar,summary_en=excluded.summary_en,author=excluded.author,tags=excluded.tags,featured=excluded.featured,published=true,metadata=excluded.metadata;
insert into public.articles (id,title,title_ar,title_en,slug,content,content_ar,content_en,summary,summary_ar,summary_en,author,tags,featured,published,views,metadata) values ('69e0ddc1-44aa-5f65-bbce-df235a2699a6','مواجهة الشائعات','مواجهة الشائعات','Zikr Article','zikr-article-expansion-20','قبل نشر خبر ديني أو اجتماعي، يسأل المسلم: ما المصدر؟ هل النص كامل؟ هل هناك مصلحة في النشر؟ التثبت يحمي الأعراض ويمنع الفتنة. وإذا تبين الخطأ، يصحح الناشر بوضوح ولا يكتفي بحذف المنشور وكأن الضرر لم يقع.','قبل نشر خبر ديني أو اجتماعي، يسأل المسلم: ما المصدر؟ هل النص كامل؟ هل هناك مصلحة في النشر؟ التثبت يحمي الأعراض ويمنع الفتنة. وإذا تبين الخطأ، يصحح الناشر بوضوح ولا يكتفي بحذف المنشور وكأن الضرر لم يقع.','Original Arabic editorial article prepared for Zikr.','قبل نشر خبر ديني أو اجتماعي، يسأل المسلم: ما المصدر؟ هل النص كامل؟ هل هناك مصلحة في النشر؟ التثبت يحمي الأعراض ويمنع الفتنة. وإذا تبين الخطأ، يصحح الناشر بوضوح ولا يكتفي بحذف المنش…','قبل نشر خبر ديني أو اجتماعي، يسأل المسلم: ما المصدر؟ هل النص كامل؟ هل هناك مصلحة في النشر؟ التثبت يحمي الأعراض ويمنع الفتنة. وإذا تبين الخطأ، يصحح الناشر بوضوح ولا يكتفي بحذف المنش…','Original article summary.','فريق تحرير ذِكر',ARRAY['إيمان','تزكية','أسرة','معرفة'],false,true,0,'{"editorial":true,"source_note":"Original editorial content; Quran and hadith references should be checked in primary sources."}') on conflict (slug) do update set title=excluded.title,title_ar=excluded.title_ar,title_en=excluded.title_en,content=excluded.content,content_ar=excluded.content_ar,content_en=excluded.content_en,summary=excluded.summary,summary_ar=excluded.summary_ar,summary_en=excluded.summary_en,author=excluded.author,tags=excluded.tags,featured=excluded.featured,published=true,metadata=excluded.metadata;
insert into public.duas (id,title_ar,title_en,slug,text_ar,text_en,occasion_ar,occasion_en,source_ar,source_en,benefits_ar,benefits_en,published,metadata) values ('1c624cb1-1c3d-5f29-9372-303d072ae139','دعاء الهداية والثبات','Zikr Dua','zikr-dua-expansion-01','اللهم اهدني وسددني، وثبت قلبي على طاعتك، واجعلني ممن يستمعون القول فيتبعون أحسنه.','Original Arabic supplication for educational use.','للمداومة على طلب الهداية والثبات، مع العمل بالأسباب وترك مواطن الفتنة.','Use with reflection and lawful practical steps.','الدعاء بصياغة أصلية تعليمية؛ تُراجع الأدعية المأثورة في كتب السنة.','Editorial source note','للمداومة على طلب الهداية والثبات، مع العمل بالأسباب وترك مواطن الفتنة.','A practical reminder connected to the supplication.',true,'{"editorial":true,"not_hadith_quote":true}') on conflict (slug) do update set title_ar=excluded.title_ar,title_en=excluded.title_en,text_ar=excluded.text_ar,text_en=excluded.text_en,occasion_ar=excluded.occasion_ar,occasion_en=excluded.occasion_en,source_ar=excluded.source_ar,source_en=excluded.source_en,benefits_ar=excluded.benefits_ar,benefits_en=excluded.benefits_en,published=true,metadata=excluded.metadata;
insert into public.duas (id,title_ar,title_en,slug,text_ar,text_en,occasion_ar,occasion_en,source_ar,source_en,benefits_ar,benefits_en,published,metadata) values ('b3dd80df-2d66-5bad-890d-1570bb3a8468','دعاء العلم النافع','Zikr Dua','zikr-dua-expansion-02','اللهم علمني ما ينفعني، وانفعني بما علمتني، وزدني علمًا وبصيرة وأدبًا، ولا تجعل علمي حجة علي.','Original Arabic supplication for educational use.','قبل الدراسة أو طلب العلم، مع تنظيم الوقت واحترام المعلم والمصدر.','Use with reflection and lawful practical steps.','صياغة دعائية تعليمية وليست حديثًا منسوبًا.','Editorial source note','قبل الدراسة أو طلب العلم، مع تنظيم الوقت واحترام المعلم والمصدر.','A practical reminder connected to the supplication.',true,'{"editorial":true,"not_hadith_quote":true}') on conflict (slug) do update set title_ar=excluded.title_ar,title_en=excluded.title_en,text_ar=excluded.text_ar,text_en=excluded.text_en,occasion_ar=excluded.occasion_ar,occasion_en=excluded.occasion_en,source_ar=excluded.source_ar,source_en=excluded.source_en,benefits_ar=excluded.benefits_ar,benefits_en=excluded.benefits_en,published=true,metadata=excluded.metadata;
insert into public.duas (id,title_ar,title_en,slug,text_ar,text_en,occasion_ar,occasion_en,source_ar,source_en,benefits_ar,benefits_en,published,metadata) values ('1dbe6e08-b191-5956-90c4-8ef11c80da62','دعاء صلاح الأسرة','Zikr Dua','zikr-dua-expansion-03','ربنا أصلح بيوتنا، وألّف بين قلوبنا، وارزقنا الرحمة والحلم وحسن التربية، واحفظ أبناءنا من السوء.','Original Arabic supplication for educational use.','للدعاء للأسرة مع الحوار والقدوة والقيام بالمسؤوليات.','Use with reflection and lawful practical steps.','دعاء أصلي مستلهم من المعاني القرآنية.','Editorial source note','للدعاء للأسرة مع الحوار والقدوة والقيام بالمسؤوليات.','A practical reminder connected to the supplication.',true,'{"editorial":true,"not_hadith_quote":true}') on conflict (slug) do update set title_ar=excluded.title_ar,title_en=excluded.title_en,text_ar=excluded.text_ar,text_en=excluded.text_en,occasion_ar=excluded.occasion_ar,occasion_en=excluded.occasion_en,source_ar=excluded.source_ar,source_en=excluded.source_en,benefits_ar=excluded.benefits_ar,benefits_en=excluded.benefits_en,published=true,metadata=excluded.metadata;
insert into public.duas (id,title_ar,title_en,slug,text_ar,text_en,occasion_ar,occasion_en,source_ar,source_en,benefits_ar,benefits_en,published,metadata) values ('ac2c16aa-e5d8-51a9-a950-4d50ebe9c172','دعاء تفريج الكرب','Zikr Dua','zikr-dua-expansion-04','يا حي يا قيوم، برحمتك أستغيث، أصلح لي شأني كله، ولا تكلني إلى نفسي طرفة عين.','Original Arabic supplication for educational use.','عند الضيق مع طلب الدعم واستعمال الوسائل المشروعة.','Use with reflection and lawful practical steps.','توجد ألفاظ مأثورة قريبة؛ راجع المصدر قبل نسبته نصًا إلى الحديث.','Editorial source note','عند الضيق مع طلب الدعم واستعمال الوسائل المشروعة.','A practical reminder connected to the supplication.',true,'{"editorial":true,"not_hadith_quote":true}') on conflict (slug) do update set title_ar=excluded.title_ar,title_en=excluded.title_en,text_ar=excluded.text_ar,text_en=excluded.text_en,occasion_ar=excluded.occasion_ar,occasion_en=excluded.occasion_en,source_ar=excluded.source_ar,source_en=excluded.source_en,benefits_ar=excluded.benefits_ar,benefits_en=excluded.benefits_en,published=true,metadata=excluded.metadata;
insert into public.duas (id,title_ar,title_en,slug,text_ar,text_en,occasion_ar,occasion_en,source_ar,source_en,benefits_ar,benefits_en,published,metadata) values ('fe8ffecc-ad43-564e-9f47-da2f52d82cb9','دعاء قضاء الدين','Zikr Dua','zikr-dua-expansion-05','اللهم اقض عني ديني، ووسع رزقي بالحلال، وبارك في سعيي، وأعني على الوفاء بحقوق الناس.','Original Arabic supplication for educational use.','مع إعداد خطة مالية صادقة، والتواصل مع أصحاب الحقوق.','Use with reflection and lawful practical steps.','صياغة أصلية للتذكير، وليست فتوى مالية.','Editorial source note','مع إعداد خطة مالية صادقة، والتواصل مع أصحاب الحقوق.','A practical reminder connected to the supplication.',true,'{"editorial":true,"not_hadith_quote":true}') on conflict (slug) do update set title_ar=excluded.title_ar,title_en=excluded.title_en,text_ar=excluded.text_ar,text_en=excluded.text_en,occasion_ar=excluded.occasion_ar,occasion_en=excluded.occasion_en,source_ar=excluded.source_ar,source_en=excluded.source_en,benefits_ar=excluded.benefits_ar,benefits_en=excluded.benefits_en,published=true,metadata=excluded.metadata;
insert into public.duas (id,title_ar,title_en,slug,text_ar,text_en,occasion_ar,occasion_en,source_ar,source_en,benefits_ar,benefits_en,published,metadata) values ('e74aa29c-6ca2-5edf-970f-2495a2224395','دعاء حسن الخلق','Zikr Dua','zikr-dua-expansion-06','اللهم ارزقني صدق اللسان، وسلامة الصدر، وحسن الخلق، واغفر لي تقصيري في حق عبادك.','Original Arabic supplication for educational use.','للمراجعة اليومية للسلوك ورد المظالم والاعتذار.','Use with reflection and lawful practical steps.','دعاء أصلي تعليمي.','Editorial source note','للمراجعة اليومية للسلوك ورد المظالم والاعتذار.','A practical reminder connected to the supplication.',true,'{"editorial":true,"not_hadith_quote":true}') on conflict (slug) do update set title_ar=excluded.title_ar,title_en=excluded.title_en,text_ar=excluded.text_ar,text_en=excluded.text_en,occasion_ar=excluded.occasion_ar,occasion_en=excluded.occasion_en,source_ar=excluded.source_ar,source_en=excluded.source_en,benefits_ar=excluded.benefits_ar,benefits_en=excluded.benefits_en,published=true,metadata=excluded.metadata;
insert into public.duas (id,title_ar,title_en,slug,text_ar,text_en,occasion_ar,occasion_en,source_ar,source_en,benefits_ar,benefits_en,published,metadata) values ('34d15011-52b1-5ff0-9dca-c154ed6f4ca8','دعاء الوالدين','Zikr Dua','zikr-dua-expansion-07','رب ارحم والدي كما ربياني صغيرًا، ووفقني لبرهما في حياتهما وبعد وفاتهما، واجزِهما عني خيرًا.','Original Arabic supplication for educational use.','بعد الصلاة وعند تذكر فضل الوالدين، مع البر العملي وصلة رحمهما.','Use with reflection and lawful practical steps.','مستلهم من الدعاء القرآني مع صياغة إضافية أصلية.','Editorial source note','بعد الصلاة وعند تذكر فضل الوالدين، مع البر العملي وصلة رحمهما.','A practical reminder connected to the supplication.',true,'{"editorial":true,"not_hadith_quote":true}') on conflict (slug) do update set title_ar=excluded.title_ar,title_en=excluded.title_en,text_ar=excluded.text_ar,text_en=excluded.text_en,occasion_ar=excluded.occasion_ar,occasion_en=excluded.occasion_en,source_ar=excluded.source_ar,source_en=excluded.source_en,benefits_ar=excluded.benefits_ar,benefits_en=excluded.benefits_en,published=true,metadata=excluded.metadata;
insert into public.duas (id,title_ar,title_en,slug,text_ar,text_en,occasion_ar,occasion_en,source_ar,source_en,benefits_ar,benefits_en,published,metadata) values ('7abcac43-79a3-5112-a193-7e529e5963df','دعاء السفر','Zikr Dua','zikr-dua-expansion-08','اللهم يسّر سفري، واحفظني ومن معي، وردنا سالمين، واجعل الطريق أمانًا وخيرًا، ووفقنا للرفق بالناس.','Original Arabic supplication for educational use.','قبل السفر مع مراجعة السلامة والوثائق والالتزام بالأنظمة.','Use with reflection and lawful practical steps.','يجمع بين معنى الدعاء المأثور وتذكير السلامة.','Editorial source note','قبل السفر مع مراجعة السلامة والوثائق والالتزام بالأنظمة.','A practical reminder connected to the supplication.',true,'{"editorial":true,"not_hadith_quote":true}') on conflict (slug) do update set title_ar=excluded.title_ar,title_en=excluded.title_en,text_ar=excluded.text_ar,text_en=excluded.text_en,occasion_ar=excluded.occasion_ar,occasion_en=excluded.occasion_en,source_ar=excluded.source_ar,source_en=excluded.source_en,benefits_ar=excluded.benefits_ar,benefits_en=excluded.benefits_en,published=true,metadata=excluded.metadata;
insert into public.duas (id,title_ar,title_en,slug,text_ar,text_en,occasion_ar,occasion_en,source_ar,source_en,benefits_ar,benefits_en,published,metadata) values ('760d19dc-90f3-5b5d-945e-c31ca1fb8c4d','دعاء للمريض','Zikr Dua','zikr-dua-expansion-09','اللهم رب الناس، أذهب البأس، واشف أنت الشافي، شفاءً يرد العافية ويعين على الصبر.','Original Arabic supplication for educational use.','لزيارة المريض أو الدعاء له، مع العلاج واستشارة المختصين.','Use with reflection and lawful practical steps.','يُراجع نص الدعاء المأثور عند النقل الحرفي.','Editorial source note','لزيارة المريض أو الدعاء له، مع العلاج واستشارة المختصين.','A practical reminder connected to the supplication.',true,'{"editorial":true,"not_hadith_quote":true}') on conflict (slug) do update set title_ar=excluded.title_ar,title_en=excluded.title_en,text_ar=excluded.text_ar,text_en=excluded.text_en,occasion_ar=excluded.occasion_ar,occasion_en=excluded.occasion_en,source_ar=excluded.source_ar,source_en=excluded.source_en,benefits_ar=excluded.benefits_ar,benefits_en=excluded.benefits_en,published=true,metadata=excluded.metadata;
insert into public.duas (id,title_ar,title_en,slug,text_ar,text_en,occasion_ar,occasion_en,source_ar,source_en,benefits_ar,benefits_en,published,metadata) values ('692743b4-99b8-5eb1-8b1a-6f3883ae2a47','دعاء التوبة','Zikr Dua','zikr-dua-expansion-10','اللهم إني ظلمت نفسي، فاغفر لي، وأعنّي على ترك الذنب ورد الحقوق وبناء بداية صالحة.','Original Arabic supplication for educational use.','بعد الندم والعزم على الإصلاح، مع رد الحقوق إلى أهلها.','Use with reflection and lawful practical steps.','صياغة تعليمية جامعة لمعاني التوبة.','Editorial source note','بعد الندم والعزم على الإصلاح، مع رد الحقوق إلى أهلها.','A practical reminder connected to the supplication.',true,'{"editorial":true,"not_hadith_quote":true}') on conflict (slug) do update set title_ar=excluded.title_ar,title_en=excluded.title_en,text_ar=excluded.text_ar,text_en=excluded.text_en,occasion_ar=excluded.occasion_ar,occasion_en=excluded.occasion_en,source_ar=excluded.source_ar,source_en=excluded.source_en,benefits_ar=excluded.benefits_ar,benefits_en=excluded.benefits_en,published=true,metadata=excluded.metadata;
insert into public.duas (id,title_ar,title_en,slug,text_ar,text_en,occasion_ar,occasion_en,source_ar,source_en,benefits_ar,benefits_en,published,metadata) values ('5d2cebbc-b949-5408-986c-faa6b47f1005','دعاء الرزق الحلال','Zikr Dua','zikr-dua-expansion-11','اللهم ارزقني رزقًا حلالًا طيبًا واسعًا، وبارك في عملي، واصرف عني الحرام والشبهات.','Original Arabic supplication for educational use.','مع الاجتهاد في العمل والتحقق من مصادر الكسب.','Use with reflection and lawful practical steps.','دعاء أصلي للتذكير.','Editorial source note','مع الاجتهاد في العمل والتحقق من مصادر الكسب.','A practical reminder connected to the supplication.',true,'{"editorial":true,"not_hadith_quote":true}') on conflict (slug) do update set title_ar=excluded.title_ar,title_en=excluded.title_en,text_ar=excluded.text_ar,text_en=excluded.text_en,occasion_ar=excluded.occasion_ar,occasion_en=excluded.occasion_en,source_ar=excluded.source_ar,source_en=excluded.source_en,benefits_ar=excluded.benefits_ar,benefits_en=excluded.benefits_en,published=true,metadata=excluded.metadata;
insert into public.duas (id,title_ar,title_en,slug,text_ar,text_en,occasion_ar,occasion_en,source_ar,source_en,benefits_ar,benefits_en,published,metadata) values ('b98d663d-162e-5198-90b8-b6823ac332f5','دعاء قبل النوم','Zikr Dua','zikr-dua-expansion-12','باسمك اللهم أحيا وأموت، اللهم اجعل نومي راحة، واغفر لي، وأيقظني على طاعتك.','Original Arabic supplication for educational use.','قبل النوم مع أذكار النوم الموثقة وترك الأجهزة مبكرًا.','Use with reflection and lawful practical steps.','تتضمن الصياغة معنى مأثورًا وإضافة أصلية.','Editorial source note','قبل النوم مع أذكار النوم الموثقة وترك الأجهزة مبكرًا.','A practical reminder connected to the supplication.',true,'{"editorial":true,"not_hadith_quote":true}') on conflict (slug) do update set title_ar=excluded.title_ar,title_en=excluded.title_en,text_ar=excluded.text_ar,text_en=excluded.text_en,occasion_ar=excluded.occasion_ar,occasion_en=excluded.occasion_en,source_ar=excluded.source_ar,source_en=excluded.source_en,benefits_ar=excluded.benefits_ar,benefits_en=excluded.benefits_en,published=true,metadata=excluded.metadata;
insert into public.duas (id,title_ar,title_en,slug,text_ar,text_en,occasion_ar,occasion_en,source_ar,source_en,benefits_ar,benefits_en,published,metadata) values ('cf50ff65-1c6d-5d96-a0fb-e4a0b6585e26','دعاء حسن الخاتمة','Zikr Dua','zikr-dua-expansion-13','اللهم أحسن خاتمتي، وثبتني عند السؤال، واجعل آخر كلامي شهادة التوحيد، واختم لي برضاك.','Original Arabic supplication for educational use.','للتذكير بالعمل الصالح وعدم تأجيل التوبة.','Use with reflection and lawful practical steps.','دعاء أصلي.','Editorial source note','للتذكير بالعمل الصالح وعدم تأجيل التوبة.','A practical reminder connected to the supplication.',true,'{"editorial":true,"not_hadith_quote":true}') on conflict (slug) do update set title_ar=excluded.title_ar,title_en=excluded.title_en,text_ar=excluded.text_ar,text_en=excluded.text_en,occasion_ar=excluded.occasion_ar,occasion_en=excluded.occasion_en,source_ar=excluded.source_ar,source_en=excluded.source_en,benefits_ar=excluded.benefits_ar,benefits_en=excluded.benefits_en,published=true,metadata=excluded.metadata;
insert into public.duas (id,title_ar,title_en,slug,text_ar,text_en,occasion_ar,occasion_en,source_ar,source_en,benefits_ar,benefits_en,published,metadata) values ('b75e3cd7-9a11-51da-856d-7e29e7e6a489','دعاء حماية القلب','Zikr Dua','zikr-dua-expansion-14','اللهم طهر قلبي من الرياء والحسد والكبر، واملأه إخلاصًا ورحمة ويقينًا.','Original Arabic supplication for educational use.','مع محاسبة النفس وترك مقارنة الناس.','Use with reflection and lawful practical steps.','دعاء أصلي مستلهم من أدعية تزكية النفس.','Editorial source note','مع محاسبة النفس وترك مقارنة الناس.','A practical reminder connected to the supplication.',true,'{"editorial":true,"not_hadith_quote":true}') on conflict (slug) do update set title_ar=excluded.title_ar,title_en=excluded.title_en,text_ar=excluded.text_ar,text_en=excluded.text_en,occasion_ar=excluded.occasion_ar,occasion_en=excluded.occasion_en,source_ar=excluded.source_ar,source_en=excluded.source_en,benefits_ar=excluded.benefits_ar,benefits_en=excluded.benefits_en,published=true,metadata=excluded.metadata;
insert into public.duas (id,title_ar,title_en,slug,text_ar,text_en,occasion_ar,occasion_en,source_ar,source_en,benefits_ar,benefits_en,published,metadata) values ('be9618bf-900b-5749-9fc9-46ba4896fe64','دعاء للمجتمع','Zikr Dua','zikr-dua-expansion-15','اللهم أصلح أحوال المسلمين، واحفظ الدماء والأعراض، وارفع الظلم، ووفق أهل الخير للإصلاح بالحكمة.','Original Arabic supplication for educational use.','للدعاء العام مع نصرة المظلوم بالطرق الآمنة والمشروعة.','Use with reflection and lawful practical steps.','دعاء أصلي لا يبرر التحريض أو العنف.','Editorial source note','للدعاء العام مع نصرة المظلوم بالطرق الآمنة والمشروعة.','A practical reminder connected to the supplication.',true,'{"editorial":true,"not_hadith_quote":true}') on conflict (slug) do update set title_ar=excluded.title_ar,title_en=excluded.title_en,text_ar=excluded.text_ar,text_en=excluded.text_en,occasion_ar=excluded.occasion_ar,occasion_en=excluded.occasion_en,source_ar=excluded.source_ar,source_en=excluded.source_en,benefits_ar=excluded.benefits_ar,benefits_en=excluded.benefits_en,published=true,metadata=excluded.metadata;
insert into public.duas (id,title_ar,title_en,slug,text_ar,text_en,occasion_ar,occasion_en,source_ar,source_en,benefits_ar,benefits_en,published,metadata) values ('d46767d6-0c4c-5ab9-a9ed-24e02e9a2e63','دعاء عند الحيرة','Zikr Dua','zikr-dua-expansion-16','اللهم اختر لي ولا تخيرني لنفسي، واهدني إلى ما فيه خير ديني ودنياي، ويسر لي أسباب الرشد.','Original Arabic supplication for educational use.','بعد جمع المعلومات والاستشارة وصلاة الاستخارة عند موضعها.','Use with reflection and lawful practical steps.','صياغة أصلية؛ مسائل الاستخارة تُراجع من مصدر موثوق.','Editorial source note','بعد جمع المعلومات والاستشارة وصلاة الاستخارة عند موضعها.','A practical reminder connected to the supplication.',true,'{"editorial":true,"not_hadith_quote":true}') on conflict (slug) do update set title_ar=excluded.title_ar,title_en=excluded.title_en,text_ar=excluded.text_ar,text_en=excluded.text_en,occasion_ar=excluded.occasion_ar,occasion_en=excluded.occasion_en,source_ar=excluded.source_ar,source_en=excluded.source_en,benefits_ar=excluded.benefits_ar,benefits_en=excluded.benefits_en,published=true,metadata=excluded.metadata;
insert into public.duas (id,title_ar,title_en,slug,text_ar,text_en,occasion_ar,occasion_en,source_ar,source_en,benefits_ar,benefits_en,published,metadata) values ('cb3d2493-e0cc-59f6-92a7-6f7c3546070b','دعاء الشكر','Zikr Dua','zikr-dua-expansion-17','الحمد لله على نعمه الظاهرة والباطنة، اللهم أعني على ذكرك وشكرك وحسن عبادتك.','Original Arabic supplication for educational use.','عند النعم والنجاح، مع استعمال النعمة في الخير.','Use with reflection and lawful practical steps.','يجمع معنى الحمد والدعاء المأثور.','Editorial source note','عند النعم والنجاح، مع استعمال النعمة في الخير.','A practical reminder connected to the supplication.',true,'{"editorial":true,"not_hadith_quote":true}') on conflict (slug) do update set title_ar=excluded.title_ar,title_en=excluded.title_en,text_ar=excluded.text_ar,text_en=excluded.text_en,occasion_ar=excluded.occasion_ar,occasion_en=excluded.occasion_en,source_ar=excluded.source_ar,source_en=excluded.source_en,benefits_ar=excluded.benefits_ar,benefits_en=excluded.benefits_en,published=true,metadata=excluded.metadata;
insert into public.duas (id,title_ar,title_en,slug,text_ar,text_en,occasion_ar,occasion_en,source_ar,source_en,benefits_ar,benefits_en,published,metadata) values ('094ec474-b1c4-5ec8-a916-51910d455bd3','دعاء ضبط اللسان','Zikr Dua','zikr-dua-expansion-18','اللهم احفظ لساني من الغيبة والكذب والبهتان، واجعل كلامي صدقًا وإصلاحًا أو صمتًا نافعًا.','Original Arabic supplication for educational use.','قبل المجالس والمراسلات ومواقع التواصل.','Use with reflection and lawful practical steps.','دعاء أصلي عملي.','Editorial source note','قبل المجالس والمراسلات ومواقع التواصل.','A practical reminder connected to the supplication.',true,'{"editorial":true,"not_hadith_quote":true}') on conflict (slug) do update set title_ar=excluded.title_ar,title_en=excluded.title_en,text_ar=excluded.text_ar,text_en=excluded.text_en,occasion_ar=excluded.occasion_ar,occasion_en=excluded.occasion_en,source_ar=excluded.source_ar,source_en=excluded.source_en,benefits_ar=excluded.benefits_ar,benefits_en=excluded.benefits_en,published=true,metadata=excluded.metadata;
insert into public.duas (id,title_ar,title_en,slug,text_ar,text_en,occasion_ar,occasion_en,source_ar,source_en,benefits_ar,benefits_en,published,metadata) values ('9aa17401-e5d4-58bd-b6d2-3496080adf3a','دعاء عند الغضب','Zikr Dua','zikr-dua-expansion-19','اللهم أعذني من ظلم نفسي والناس، وارزقني حلمًا يوقف الأذى، وبصيرة تعينني على الاعتذار والإصلاح.','Original Arabic supplication for educational use.','مع السكوت والوضوء والابتعاد المؤقت عن سبب الغضب.','Use with reflection and lawful practical steps.','دعاء أصلي مع إرشاد سلوكي.','Editorial source note','مع السكوت والوضوء والابتعاد المؤقت عن سبب الغضب.','A practical reminder connected to the supplication.',true,'{"editorial":true,"not_hadith_quote":true}') on conflict (slug) do update set title_ar=excluded.title_ar,title_en=excluded.title_en,text_ar=excluded.text_ar,text_en=excluded.text_en,occasion_ar=excluded.occasion_ar,occasion_en=excluded.occasion_en,source_ar=excluded.source_ar,source_en=excluded.source_en,benefits_ar=excluded.benefits_ar,benefits_en=excluded.benefits_en,published=true,metadata=excluded.metadata;
insert into public.duas (id,title_ar,title_en,slug,text_ar,text_en,occasion_ar,occasion_en,source_ar,source_en,benefits_ar,benefits_en,published,metadata) values ('07073641-8fad-56d9-bf52-c91b8ba30659','دعاء للناشئة','Zikr Dua','zikr-dua-expansion-20','اللهم حبب إلى أبنائنا الإيمان والعلم والصدق، واحفظهم، واجعلهم نفعًا لأهلهم ومجتمعهم.','Original Arabic supplication for educational use.','للدعاء للأطفال مع التربية والمتابعة والقدوة.','Use with reflection and lawful practical steps.','دعاء أصلي مناسب للأسرة.','Editorial source note','للدعاء للأطفال مع التربية والمتابعة والقدوة.','A practical reminder connected to the supplication.',true,'{"editorial":true,"not_hadith_quote":true}') on conflict (slug) do update set title_ar=excluded.title_ar,title_en=excluded.title_en,text_ar=excluded.text_ar,text_en=excluded.text_en,occasion_ar=excluded.occasion_ar,occasion_en=excluded.occasion_en,source_ar=excluded.source_ar,source_en=excluded.source_en,benefits_ar=excluded.benefits_ar,benefits_en=excluded.benefits_en,published=true,metadata=excluded.metadata;
insert into public.kids_content (id,title_ar,title_en,slug,type,content_ar,content_en,age_group,quiz_data,published,is_active,metadata) values ('a52df769-e853-598e-9c89-19a3f68dffcc','قصة الصدق مع التاجر الصغير','Zikr Kids Content','zikr-kids-expansion-01','story','قصة تفاعلية عن طفل وجد خطأ في حساب متجر، فأخبر صاحبه رغم أن الاحتفاظ بالمال كان أسهل. يتعلم الطفل أن الأمانة تحمي القلب وثقة الناس.','Original educational content prepared for families.','3-5',NULL,true,true,'{"editorial":true,"source_note":"Original educational adaptation; parents should guide age-appropriate use."}') on conflict (slug) do update set title_ar=excluded.title_ar,title_en=excluded.title_en,type=excluded.type,content_ar=excluded.content_ar,content_en=excluded.content_en,age_group=excluded.age_group,quiz_data=excluded.quiz_data,published=true,is_active=true,metadata=excluded.metadata;
insert into public.kids_content (id,title_ar,title_en,slug,type,content_ar,content_en,age_group,quiz_data,published,is_active,metadata) values ('4a4cada8-4cb4-5bac-b21c-18c0b21dcc9e','رحلة قطرة الماء','Zikr Kids Content','zikr-kids-expansion-02','story','تتبع القصة قطرة ماء من السحاب إلى البيت، وتشرح للطفل لماذا نغلق الصنبور ولا نسرف، وأن شكر النعمة يكون بحسن استخدامها.','Original educational content prepared for families.','3-5',NULL,true,true,'{"editorial":true,"source_note":"Original educational adaptation; parents should guide age-appropriate use."}') on conflict (slug) do update set title_ar=excluded.title_ar,title_en=excluded.title_en,type=excluded.type,content_ar=excluded.content_ar,content_en=excluded.content_en,age_group=excluded.age_group,quiz_data=excluded.quiz_data,published=true,is_active=true,metadata=excluded.metadata;
insert into public.kids_content (id,title_ar,title_en,slug,type,content_ar,content_en,age_group,quiz_data,published,is_active,metadata) values ('c1a2e628-125d-5a6e-b7e9-dd07bdee93dc','سلمى وتعاون الجيران','Zikr Kids Content','zikr-kids-expansion-03','story','تتعلم سلمى أن مساعدة الجار لا تحتاج إلى مال؛ يمكنها حمل كتاب أو مشاركة طعام أو سؤال كبير السن عن حاجته.','Original educational content prepared for families.','6-8',NULL,true,true,'{"editorial":true,"source_note":"Original educational adaptation; parents should guide age-appropriate use."}') on conflict (slug) do update set title_ar=excluded.title_ar,title_en=excluded.title_en,type=excluded.type,content_ar=excluded.content_ar,content_en=excluded.content_en,age_group=excluded.age_group,quiz_data=excluded.quiz_data,published=true,is_active=true,metadata=excluded.metadata;
insert into public.kids_content (id,title_ar,title_en,slug,type,content_ar,content_en,age_group,quiz_data,published,is_active,metadata) values ('34fc06e3-583f-58d7-9dba-1dab5cf2e6d2','مفتاح الصلاة','Zikr Kids Content','zikr-kids-expansion-04','game','لعبة ترتيب خمس بطاقات للصلاة والوضوء والنية والوقت، مع تفسير بسيط يربط الصلاة بالطمأنينة.','Original educational content prepared for families.','6-8','{"questions":[{"text":"ما السلوك الأفضل؟","options":["الصدق والتعاون","السخرية","الإسراف","نشر الخبر بلا تحقق"],"correctAnswer":0}],"reward":"وسام العمل الصالح"}',true,true,'{"editorial":true,"source_note":"Original educational adaptation; parents should guide age-appropriate use."}') on conflict (slug) do update set title_ar=excluded.title_ar,title_en=excluded.title_en,type=excluded.type,content_ar=excluded.content_ar,content_en=excluded.content_en,age_group=excluded.age_group,quiz_data=excluded.quiz_data,published=true,is_active=true,metadata=excluded.metadata;
insert into public.kids_content (id,title_ar,title_en,slug,type,content_ar,content_en,age_group,quiz_data,published,is_active,metadata) values ('f79a43d5-aee3-5df5-be19-962e3cce1bc7','صيد الكلمات الطيبة','Zikr Kids Content','zikr-kids-expansion-05','game','لعبة يختار فيها الطفل كلمات مثل شكرًا وآسف من بين كلمات مؤذية، ثم يركب جملة إصلاحية.','Original educational content prepared for families.','6-8','{"questions":[{"text":"ما السلوك الأفضل؟","options":["الصدق والتعاون","السخرية","الإسراف","نشر الخبر بلا تحقق"],"correctAnswer":0}],"reward":"وسام العمل الصالح"}',true,true,'{"editorial":true,"source_note":"Original educational adaptation; parents should guide age-appropriate use."}') on conflict (slug) do update set title_ar=excluded.title_ar,title_en=excluded.title_en,type=excluded.type,content_ar=excluded.content_ar,content_en=excluded.content_en,age_group=excluded.age_group,quiz_data=excluded.quiz_data,published=true,is_active=true,metadata=excluded.metadata;
insert into public.kids_content (id,title_ar,title_en,slug,type,content_ar,content_en,age_group,quiz_data,published,is_active,metadata) values ('c2371bb7-186e-529c-a749-02cdb22d50c8','يوسف والصبر الجميل','Zikr Kids Content','zikr-kids-expansion-06','story','قصة مبسطة مستلهمة من المعاني الثابتة في سورة يوسف، تركز على عدم اليأس والعفو دون اختراع حوارات منسوبة للوحي.','Original educational content prepared for families.','6-8',NULL,true,true,'{"editorial":true,"source_note":"Original educational adaptation; parents should guide age-appropriate use."}') on conflict (slug) do update set title_ar=excluded.title_ar,title_en=excluded.title_en,type=excluded.type,content_ar=excluded.content_ar,content_en=excluded.content_en,age_group=excluded.age_group,quiz_data=excluded.quiz_data,published=true,is_active=true,metadata=excluded.metadata;
